<?php
/**
 * ChatHelp — apply-logoimg (CH_LOGO_IMG) — YENI "CHelp" logosunu her ikona yazar.
 *  512 base64 -> GD ile 16/32/64/180/192/512 + ch-logo-512.png + ch-word.png.
 *  favicon/apple-touch/PWA/manifest ayni dosya adlarina yazildigi icin HER YERDE guncellenir.
 *  Sadece '.png?a3' -> '.png?a7' cache-bump (HTML). Alfa (yuvarlak kose) korunur.
 * KULLANIM: pull2.php?key=...&files=apply-logoimg.php
 */
header('Content-Type: text/plain; charset=UTF-8');
error_reporting(E_ERROR | E_PARSE);
echo "apply-logoimg BASLADI OK (PHP ".PHP_VERSION.")\n\n";
$D=__DIR__;
if(!function_exists('imagecreatefromstring')){ echo "✗ GD yok\n"; exit; }
$B512="";
$BWORD="";

$src=@imagecreatefromstring(base64_decode($B512));
if(!$src){ echo "✗ 512 decode edilemedi\n"; exit; }
$sw=imagesx($src);
function saveSize($src,$sw,$sz,$path){
  $im=imagecreatetruecolor($sz,$sz);
  imagealphablending($im,false); imagesavealpha($im,true);
  $tr=imagecolorallocatealpha($im,0,0,0,127); imagefilledrectangle($im,0,0,$sz,$sz,$tr);
  imagecopyresampled($im,$src,0,0,0,0,$sz,$sz,$sw,$sw);
  $ok=imagepng($im,$path,6); imagedestroy($im); return $ok;
}
$sizes=[16=>'icon-16.png',32=>'icon-32.png',64=>'icon-64.png',180=>'icon-180.png',192=>'icon-192.png',512=>'icon-512.png'];
$done=[];
foreach($sizes as $sz=>$name){
  if(saveSize($src,$sw,$sz,"$D/$name")){ $done[]="$name(".$sz.")"; } else echo "  ✗ $name yazilamadi\n";
}
/* ch-logo-512.png (ham 512) */
@file_put_contents("$D/ch-logo-512.png",base64_decode($B512));
/* ch-word.png (header wordmark) */
@file_put_contents("$D/ch-word.png",base64_decode($BWORD));
imagedestroy($src);
echo "  ✓ ikonlar yazildi: ".implode(', ',$done)."\n";
echo "  ✓ ch-logo-512.png + ch-word.png yazildi\n";

/* cache-bump: .png?a3 -> .png?a7 (favicon/apple-touch HTML) */
$idx="$D/index.php"; $s=@file_get_contents($idx);
if($s!==false){
  $c=0; $s=str_replace('.png?a3','.png?a7',$s,$c);
  if($c>0){
    $tmp=tempnam(sys_get_temp_dir(),'lg').'.php'; file_put_contents($tmp,$s);
    $lo=[];$rc=0; exec('php -l '.escapeshellarg($tmp).' 2>&1',$lo,$rc); @unlink($tmp);
    if($rc===0){ @file_put_contents($idx.'.bak-logoimg-'.date('Ymd-His'),(string)@file_get_contents($idx)); @file_put_contents($idx,$s); if(function_exists('opcache_reset'))@opcache_reset(); echo "  ✓ index.php cache-bump .png?a3 -> ?a7 ($c yer)\n"; }
    else echo "  ✗ index lint hatasi — cache-bump atlandi\n";
  } else echo "  = '.png?a3' bulunamadi (belki farkli surum)\n";
}
echo "\n  ✓ CH_LOGO_IMG bitti. favicon/PWA/apple-touch HER YERDE yeni CHelp logosu.\n";
echo "  App'i tam kapat-ac (ikon cache). Header/menu ayri adimda (Deploy 2).\n";
